PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
DROP TABLE IF EXISTS "app_auditlog";
DROP TABLE IF EXISTS "app_maintenancerecord";
DROP TABLE IF EXISTS "app_returnrecord";
DROP TABLE IF EXISTS "app_loanrecord";
DROP TABLE IF EXISTS "app_unitallocation";
DROP TABLE IF EXISTS "app_requestitem";
DROP TABLE IF EXISTS "app_borrowrequest";
DROP TABLE IF EXISTS "app_equipmentunit";
DROP TABLE IF EXISTS "app_catalogitem";
DROP TABLE IF EXISTS "app_category";
DROP TABLE IF EXISTS "app_profile";
DROP TABLE IF EXISTS "app_user";
DROP TABLE IF EXISTS "app_systemsetting";
CREATE TABLE "app_systemsetting" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "max_borrow_quantity" integer NOT NULL, "max_borrow_days" integer NOT NULL);
CREATE TABLE "app_user" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "password" varchar(128) NOT NULL, "email" varchar(254) NOT NULL UNIQUE, "role" integer NOT NULL, "status" integer NOT NULL, "last_login" datetime NULL);
CREATE TABLE "app_profile" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "first_name" varchar(64) NOT NULL, "last_name" varchar(64) NOT NULL, "contact_number" varchar(11) NOT NULL, "created_at" datetime NOT NULL, "user_id" bigint NOT NULL UNIQUE REFERENCES "app_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "app_category" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(64) NOT NULL, "description" varchar(254) NOT NULL, "status" integer NOT NULL, "created_at" datetime NOT NULL);
CREATE TABLE "app_catalogitem" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(64) NOT NULL, "description" varchar(254) NOT NULL, "status" integer NOT NULL, "category_id" bigint NOT NULL REFERENCES "app_category" ("id") DEFERRABLE INITIALLY DEFERRED, "created_at" datetime NOT NULL);
CREATE TABLE "app_equipmentunit" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "asset_code" varchar(64) NOT NULL, "inventory_status" integer NOT NULL, "condition" integer NOT NULL, "acquired_at" datetime NOT NULL, "catalog_item_id" bigint NOT NULL REFERENCES "app_catalogitem" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "app_borrowrequest" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "created_at" datetime NOT NULL, "user_id" bigint NOT NULL REFERENCES "app_user" ("id") DEFERRABLE INITIALLY DEFERRED, "purpose" varchar(254) NOT NULL, "due_at" datetime NOT NULL, "status" integer NOT NULL, "rejection_reason" text NOT NULL DEFAULT '');
CREATE TABLE "app_requestitem" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "quantity" integer unsigned NOT NULL CHECK ("quantity" >= 0), "borrow_request_id" bigint NOT NULL REFERENCES "app_borrowrequest" ("id") DEFERRABLE INITIALLY DEFERRED, "catalog_item_id" bigint NOT NULL REFERENCES "app_catalogitem" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "unique_catalog_item_per_request" UNIQUE ("borrow_request_id", "catalog_item_id"), CONSTRAINT "request_item_quantity_gte_1" CHECK ("quantity" >= 1));
CREATE TABLE "app_unitallocation" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "status" integer NOT NULL, "allocated_at" datetime NOT NULL, "equipment_unit_id" bigint NOT NULL REFERENCES "app_equipmentunit" ("id") DEFERRABLE INITIALLY DEFERRED, "request_item_id" bigint NOT NULL REFERENCES "app_requestitem" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "app_loanrecord" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "created_at" datetime NOT NULL, "borrow_request_id" bigint NOT NULL REFERENCES "app_borrowrequest" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" bigint NOT NULL REFERENCES "app_user" ("id") DEFERRABLE INITIALLY DEFERRED, "released_at" datetime NULL);
CREATE TABLE "app_returnrecord" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "condition" integer NOT NULL, "created_at" datetime NOT NULL, "borrow_request_id" bigint NOT NULL REFERENCES "app_borrowrequest" ("id") DEFERRABLE INITIALLY DEFERRED, "equipment_unit_id" bigint NOT NULL REFERENCES "app_equipmentunit" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "app_maintenancerecord" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "issue" varchar(254) NOT NULL, "action" varchar(254) NOT NULL, "status" integer NOT NULL, "created_at" datetime NOT NULL, "resolved_at" datetime NOT NULL, "maintainer_id" bigint NOT NULL REFERENCES "app_user" ("id") DEFERRABLE INITIALLY DEFERRED, "unit_id" bigint NOT NULL REFERENCES "app_equipmentunit" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "app_auditlog" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "action" varchar(254) NOT NULL, "created_at" datetime NOT NULL, "user_id" bigint NOT NULL REFERENCES "app_user" ("id") DEFERRABLE INITIALLY DEFERRED);
COMMIT;
